if(getenv('LOKA_APPROVAL_PREVIEW'))file_put_contents(getenv('LOKA_APPROVAL_PREVIEW').'/center.html',$html);
foreach(['approved'=>$ownApproved,'rejected'=>$ownRejected] as $state=>$id){$v=workspacePage(['status'=>$state]);ok($v->getData()['users']->pluck('id')->contains($id),'Center '.$state.' tab works');}
$d=workspacePage(['status'=>'approved','courier_type'=>'driver','q'=>'Courier Approved'])->getData();ok($d['users']->total()===1&&$d['users']->first()->id===$ownApproved,'Driver filter and search combine');ok(workspacePage(['q'=>'%'])->getData()['users']->total()===0,'Search wildcard is treated literally');ok(workspacePage(['q'=>'nonexistent'])->getData()['users']->total()===0,'Search empty state has no leaked applicants');
$html=workspacePage(['q'=>'nonexistent'])->render();ok(str_contains($html,'No matching applications')&&str_contains($html,'Reset filters'),'Empty filtered state renders reset control');ok($controller->document($riderDoc)->getFile()->isFile(),'Center opens own courier document');workspaceDenied(fn()=>$controller->document($otherDoc),403,'Center cannot open other company document');workspaceDenied(fn()=>$controller->document($doc),403,'Center cannot open sorting center registration document');
workspaceDenied(fn()=>$controller->approve(requestFor(['decision'=>'approved']),$otherCourier),403,'Center cannot approve another company courier');
try{$controller->approve(requestFor(['decision'=>'rejected','reason'=>'short']),$ownPending);throw new RuntimeException('Short rejection accepted');}catch(ValidationException $e){ok(isset($e->errors()['reason']),'Rejection requires meaningful reason');}
$controller->approve(requestFor(['decision'=>'approved']),$ownPending);ok(DB::table('users')->find($ownPending)->approval_status==='approved','Center approval updates existing application');ok(!workspacePage()->getData()['users']->pluck('id')->contains($ownPending),'Approved courier leaves pending tab');ok(workspacePage(['status'=>'approved'])->getData()['users']->pluck('id')->contains($ownPending),'Approved courier appears on approved tab');workspaceDenied(fn()=>$controller->approve(requestFor(['decision'=>'approved']),$ownPending),422,'Already reviewed application cannot be approved twice');
loginAs($logAdmin);$controller->approve(requestFor(['decision'=>'rejected','reason'=>'The SEC certificate image is not readable.']),$pending);$u=DB::table('users')->find($pending);ok($u->approval_status==='rejected'&&str_contains($u->rejection_reason,'SEC certificate'),'Admin rejection stores decision and reason');ok(workspacePage(['status'=>'rejected','q'=>'Approval Pending'])->getData()['users']->total()===1,'New rejection appears under rejected with search');ok(DB::table('notifications')->where('user_id',$pending)->where('body','like','Application rejected%')->exists(),'Existing notification process still runs');
